('tst-meridian-health', 'The live dispatch board matches how our coordinators actually work — no more tracking availability across five phone lines.', 'Operations Lead', 'Regional healthcare network · Meridian Health case study', 'prj-meridian-health', true, 1),
('tst-harvestlink', 'We went from word-of-mouth sales to a searchable listing our buyers actually use.', 'Founder', 'Agricultural marketplace · HarvestLink case study', 'prj-harvestlink', true, 2),
('tst-swiftaid', 'Drivers adopted the partner app faster than we expected, because it respects how little time they have to look at a screen.', 'Fleet Coordinator', 'Emergency transport network · SwiftAid case study', 'prj-swiftaid', true, 3),
('tst-vantage-goods', 'Checkout finally feels as fast on a phone as it does on a laptop.', 'E-commerce Manager', 'Multi-category retailer · Vantage Goods case study', 'prj-vantage-goods', true, 4),
('tst-openhands', 'The new site gives donors something to point to. It finally looks like the organization we actually are.', 'Program Director', 'Community nonprofit · OpenHands case study', 'prj-openhands', true, 5),
('tst-ledgerly', 'Our organic traffic stopped bleeding out within the first month of the technical fixes landing.', 'Head of Marketing', 'B2B fintech tools provider · Ledgerly case study', 'prj-ledgerly', true, 6)
ON CONFLICT (id) DO NOTHING;
